-- Dopo la migrazione; solo fixture sintetiche, nessun dato reale modificato.
begin;
do $claims$ begin perform set_config('request.jwt.claim.sub',(select user_id::text from public.portal_admins order by user_id limit 1),true);end $claims$;
set local role authenticated;
do $test$
declare client uuid; sid uuid; actual uuid; manual jsonb; old_manual jsonb; ship jsonb; actual_row jsonb; result jsonb; snap jsonb; failed boolean; admin_claim text;
begin
 admin_claim:=current_setting('request.jwt.claim.sub');
 insert into public.portal_clients(name,billing_rules,minimum_logistics,vat_rate) values('Test costo manuale '||gen_random_uuid(),'[]',0,22) returning id into client;
 insert into public.portal_shipments(client_id,code,shipped_on,recipient,carrier,tracking) values(client,'MANUAL-TEST-'||gen_random_uuid(),'2099-11-05','Destinatario sintetico','BRT','TRACK-TEST') returning id into sid;
 select to_jsonb(s) into ship from public.portal_shipments s where id=sid;
 manual:=public.portal_save_manual_carrier_cost(sid,5.60,ship);
 assert (manual->>'manual_provisional')::boolean and (manual->>'shipment_id')::uuid=sid;
 assert (select customer_charge=5.60 and client_id=client from public.portal_shipments where id=sid),'Costo/cliente non corretti';
 snap:=public.portal_section_snapshot(client,'2099-11-01','carriers');
 assert (snap->>'carrier_total')::numeric=5.60 and (snap->>'unmatched_shipments')::int=0 and (snap->>'missing_charges')::int=0,'Costo non entrato nella fatturazione';
 snap:=public.portal_validate_section(client,'2099-11-01','carriers');
 assert snap->>'preinvoice_error' is null,'Prefattura non generata';
 assert (select invoice_lines @> '[{"basis":"carrier_total","amount":5.60}]'::jsonb from public.portal_months where client_id=client and month='2099-11-01'),'Costo non presente nella prefattura';
 select to_jsonb(s) into ship from public.portal_shipments s where id=sid;
 failed:=false;begin perform public.portal_save_manual_carrier_cost(sid,5.60,ship);exception when others then failed:=sqlerrm like 'Spedizione con costo già presente:%';end;assert failed,'Duplicato manuale ammesso';
 failed:=false;begin perform public.portal_save_manual_carrier_cost(sid,5.601,ship,(manual->>'id')::uuid,manual);exception when others then failed:=sqlerrm like 'Inserisci un importo%';end;assert failed,'Più di due decimali ammessi';
 failed:=false;begin perform public.portal_save_manual_carrier_cost(sid,-1,ship,(manual->>'id')::uuid,manual);exception when others then failed:=sqlerrm like 'Inserisci un importo%';end;assert failed,'Importo negativo ammesso';
 old_manual:=manual;
 manual:=public.portal_save_manual_carrier_cost(sid,5.75,ship,(manual->>'id')::uuid,manual);
 assert (select customer_charge=5.75 from public.portal_shipments where id=sid),'Modifica importo non applicata';
 assert not exists(select 1 from public.portal_section_validations where client_id=client and month='2099-11-01' and section='carriers'),'Convalida non invalidata';
 failed:=false;begin perform public.portal_save_manual_carrier_cost(sid,6,ship,(manual->>'id')::uuid,old_manual);exception when others then failed:=sqlerrm like 'Spedizione o importo modificato:%';end;assert failed,'Anteprima scaduta accettata';
 insert into public.portal_carrier_charges(invoice_number,month,carrier_code,reference,recipient,shipped_on,transport,fuel) values('BRT TEST','2099-12-01',gen_random_uuid()::text,'TRACK-TEST','Destinatario sintetico','2099-11-05',5.75,.20) returning id into actual;
 select to_jsonb(c) into actual_row from public.portal_carrier_charges c where id=actual;
 failed:=false;begin perform public.portal_assign_carrier_destination(actual,false,sid,actual_row);exception when others then failed:=sqlerrm like 'Spedizione con costo già presente:%';end;assert failed,'Fattura sommata al costo manuale';
 select to_jsonb(s) into ship from public.portal_shipments s where id=sid;
 failed:=false;begin perform public.portal_replace_manual_carrier_cost((manual->>'id')::uuid,actual,old_manual,actual_row,ship);exception when others then failed:=sqlerrm like 'Costi o spedizione modificati:%';end;assert failed,'Sostituzione con dati scaduti ammessa';
 assert exists(select 1 from public.portal_carrier_charges where id=(manual->>'id')::uuid),'Costo cancellato dopo sostituzione fallita';
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 failed:=false;begin perform public.portal_save_manual_carrier_cost(sid,6,ship);exception when insufficient_privilege then failed:=true;end;assert failed,'Accesso non admin ammesso';
 perform set_config('request.jwt.claim.sub',admin_claim,true);
 result:=public.portal_replace_manual_carrier_cost((manual->>'id')::uuid,actual,manual,actual_row,ship);
 assert (result->>'shipment_id')::uuid=sid and not (result->>'manual_provisional')::boolean;
 assert not exists(select 1 from public.portal_carrier_charges where id=(manual->>'id')::uuid),'Costo manuale non rimosso';
 assert (select count(*)=1 from public.portal_carrier_charges where shipment_id=sid),'Doppio costo dopo sostituzione';
 assert (select customer_charge=5.95 from public.portal_shipments where id=sid),'Nuovo importo non applicato';
 snap:=public.portal_section_snapshot(client,'2099-11-01','carriers');
 assert (snap->>'carrier_total')::numeric=5.95,'Costi sommati invece di sostituiti';
 snap:=public.portal_validate_section(client,'2099-11-01','carriers');
 assert snap->>'preinvoice_error' is null;
 assert (select invoice_lines @> '[{"basis":"carrier_total","amount":5.95}]'::jsonb from public.portal_months where client_id=client and month='2099-11-01'),'Nuovo importo non entrato in prefattura';
 assert not has_function_privilege('anon','public.portal_save_manual_carrier_cost(uuid,numeric,jsonb,uuid,jsonb)','EXECUTE');
 assert not has_function_privilege('anon','public.portal_replace_manual_carrier_cost(uuid,uuid,jsonb,jsonb,jsonb)','EXECUTE');
end $test$;
select 'Costi manuali: creazione, fatturazione, modifica, controlli, sostituzione e autorizzazioni superati' as esito;
rollback;
